function loadMonsterKills() { try { return JSON.parse(localStorage.getItem('robMonsterKills')||'{}'); } catch(e) { return {}; } }
function saveMonsterKills() { try { localStorage.setItem('robMonsterKills', JSON.stringify(monsterKills)); } catch(e) {} }
function loadMonsterMilestones() { try { return JSON.parse(localStorage.getItem('robMonsterMilestones')||'{}'); } catch(e) { return {}; } }
function saveMonsterMilestones() { try { localStorage.setItem('robMonsterMilestones', JSON.stringify(monsterNextMilestone)); } catch(e) {} }
function loadMonsterMilestoneCount() { try { return JSON.parse(localStorage.getItem('robMonsterMileCount')||'{}'); } catch(e) { return {}; } }
function saveMonsterMilestoneCount() { try { localStorage.setItem('robMonsterMileCount', JSON.stringify(monsterMilestoneCount)); } catch(e) {} }

let monsterKills = loadMonsterKills();
let monsterNextMilestone = loadMonsterMilestones();
let monsterMilestoneCount = loadMonsterMilestoneCount();

function checkMonsterMilestone(type) {
  const lex = MONSTER_LEXICON.find(function(m){ return m.id === type; });
  if (!lex) return;
  if (monsterNextMilestone[type] === undefined) monsterNextMilestone[type] = lex.firstMilestone;
  if (monsterMilestoneCount[type] === undefined) monsterMilestoneCount[type] = 0;
  const kills = monsterKills[type] || 0;
  const next = monsterNextMilestone[type];
  if (kills >= next) {
    const count = monsterMilestoneCount[type];
    const reward = 10 + count * 10; // 10, 20, 30, 40, ... per milestone
    if (meta) { meta.diamonds += reward; globalDiamonds += reward; saveDiamonds(globalDiamonds); }
    log('\uD83C\uDFC6 <span style="color:#44ddff"><b>' + lex.name + '</b> Lexikon-Meilenstein #' + (count+1) + ': ' + next + ' Kills! +' + reward + ' Diamanten!</span>');
    monsterNextMilestone[type] = next * 2;
    monsterMilestoneCount[type] = count + 1;
    saveMonsterMilestones();
    saveMonsterMilestoneCount();
  }
}

function showMonsterLexicon() {
  var modal = document.getElementById('monsterLexikonModal');
  if (modal) { renderMonsterLexikon(); modal.style.display = 'flex'; return; }
  modal = document.createElement('div');
  modal.id = 'monsterLexikonModal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:500;display:flex;align-items:flex-start;justify-content:center;background:rgba(0,0,0,0.95);overflow-y:auto;padding:20px';
  modal.innerHTML = '<div style="background:linear-gradient(145deg,#050a05,#0a150a);border:2px solid #44aa44;border-radius:16px;padding:22px 18px;max-width:420px;width:95%">'
    + '<h2 style="font-family:\'Cinzel Decorative\',serif;color:#44ff88;font-size:1.1rem;margin-bottom:6px;text-align:center">\uD83D\uDCDA MONSTER LEXIKON</h2>'
    + '<p style="color:#446644;font-size:0.65rem;text-align:center;margin-bottom:16px">T\u00F6te Monster um sie freizuschalten und Diamanten-Boni zu erhalten!</p>'
    + '<div id="monsterLexikonGrid" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:16px"></div>'
    + '<button class="btn btn-wide" onclick="closeMonsterLexikon()" style="width:100%;border-color:#44aa44;color:#44ff88">\u2190 ZURUECK</button>'
    + '</div>';
  document.body.appendChild(modal);
  renderMonsterLexikon();
}

function renderMonsterLexikon() {
  var grid = document.getElementById('monsterLexikonGrid');
  if (!grid) return;
  grid.innerHTML = MONSTER_LEXICON.map(function(m) {
    var kills = monsterKills[m.id] || 0;
    var seen = kills > 0;
    var nextMs = monsterNextMilestone[m.id] !== undefined ? monsterNextMilestone[m.id] : m.firstMilestone;
    var pct = seen ? Math.min(100, Math.round(kills / nextMs * 100)) : 0;
    var border = seen ? '#44aa44' : '#1a2a1a';
    var bg = seen ? 'rgba(0,30,10,0.8)' : 'rgba(5,10,5,0.8)';
    return '<div style="border:1px solid ' + border + ';border-radius:10px;padding:8px 6px;text-align:center;background:' + bg + '">'
      + '<img src="' + m.img + '" style="width:56px;height:56px;border-radius:6px;object-fit:cover;' + (seen ? '' : 'filter:grayscale(100%) brightness(0.3)') + '">'
      + '<div style="font-size:0.6rem;font-family:Cinzel,serif;color:' + (seen ? '#44ff88' : '#446644') + ';margin-top:4px;font-weight:700">' + (seen ? m.name : '???') + '</div>'
      + (seen
        ? '<div style="font-size:0.55rem;color:#88cc88;margin:2px 0">' + kills.toLocaleString('de') + ' get\u00F6tet</div>'
          + '<div style="font-size:0.5rem;color:#446644;margin-bottom:3px">N\u00E4chster Bonus: ' + nextMs.toLocaleString('de') + '</div>'
          + '<div style="background:#0a1a0a;border-radius:3px;height:4px;overflow:hidden"><div style="background:#44aa44;width:' + pct + '%;height:100%;border-radius:3px"></div></div>'
        : '<div style="font-size:0.5rem;color:#2a4a2a;margin-top:4px">Noch nicht entdeckt</div>')
      + '</div>';
  }).join('');
}

function closeMonsterLexikon() {
  var m = document.getElementById('monsterLexikonModal');
  if (m) m.style.display = 'none';
  openMenu();
}

