function getCompletedQuestCount() {
  const hd = heroData;
  return QUEST_LIST.filter(q => {
    const val = q.getValue.length === 2 ? q.getValue(questTracking, hd) : q.getValue(questTracking, hd);
    return val >= q.target;
  }).length;
}
function getClassLevel() {
  // Erst ab Helden-Level 10 und nach Klassenwahl freigeschaltet
  if (!meta || !meta.hero) return 0;
  return Math.min(100, getCompletedQuestCount());
}

