// ===== GAME STATE =====
let meta = {};
let board=[], pos=0, inFight=false, monstersInFight=[], revengeStacks=0;

function initMeta(hero, name) {
  const hd = heroData[hero];
  const heroLevel = getHeroLevel(hero);
  let maxHp = 20;
  let atk = 5;
  // Level bonus: +2 ATK, +5 HP per level
  maxHp += heroLevel * 5;
  atk  += heroLevel * 2;
  // Skill: Zaehigkeit (ben2) = +15 HP per level
  if (hd.skills.includes('ben2')) maxHp += heroLevel * 15;
  // Skill: Kriegskunst (ben4) = +3 ATK per level
  if (hd.skills.includes('ben4')) atk += heroLevel * 3;
  // Apply persistent shop bonuses
  maxHp += shopBonuses.hp;
  atk += shopBonuses.atk;
  if (typeof cityBonus === 'function') { maxHp += cityBonus('hp'); atk += cityBonus('atk'); }
  // Apply class passives permanently (all active classes)
  var _activeCls = typeof playerClasses !== 'undefined' ? playerClasses : (playerClass ? [playerClass] : []);
  _activeCls.forEach(function(cls) {
    if (cls.hpMult) maxHp = Math.floor(maxHp * (1 + cls.hpMult));
    if (cls.atkMult) atk = Math.floor(atk * (1 + cls.atkMult));
  });
  // Apply equipped item bonuses permanently
  if (typeof getEquippedBonuses === 'function') {
    var _eqb = getEquippedBonuses();
    maxHp += _eqb.hp;
    atk += _eqb.atk;
  }
  const savedGold = loadPersistentGold();
  meta = {
    name, hero, hp: maxHp, maxHp, attack: atk, gold: savedGold, diamonds: globalDiamonds,
    round: 1, kills: 0, bossKillsThisRun: 0, bestRound: 1, revengeStacks: 0,
    energie: 0
  };
  // Reset ability cooldowns for new game
  if (typeof abilityCooldowns !== 'undefined') abilityCooldowns = {};
  if (typeof shieldActive !== 'undefined') shieldActive = false;
  if (typeof hinterhaltAvailable !== 'undefined') hinterhaltAvailable = true;
  if (typeof hiebAvailable !== 'undefined') hiebAvailable = true;
}

// Helden-Level basiert auf Monster-Kills: Level 1 = 150 Kills, Level 2 = 300, Level 3 = 450 etc (linear +150 pro Level)
function getHeroLevel(hero) {
  const kills = heroData[hero].kills || 0;
  return Math.min(100, Math.floor(kills / 150));
}

// wie viele Kills seit Beginn des aktuellen Levels
function getKillsThisLevel(hero) {
  const kills = heroData[hero].kills || 0;
  const level = getHeroLevel(hero);
  const killsForThisLevel = level * 150;
  return kills - killsForThisLevel;
}

// erforderliche Kills für den aktuellen Levelschritt
function getKillsForNext(hero) {
  return 150;
}
function getHeroKillsToNext(hero) {
  const kills = heroData[hero].kills || 0;
  const lv = getHeroLevel(hero);
  if (lv >= 100) return 0;
  let cumulative = 0;
  for (let i = 1; i <= lv; i++) {
    cumulative += 150 * Math.pow(2, i - 1);
  }
  const nextCumulative = cumulative + 150 * Math.pow(2, lv);
  return nextCumulative - kills;
}

// ===== HERO SELECT =====
function selectHero(el) {
  document.querySelectorAll('.hero-card').forEach(c => c.classList.remove('selected'));
  el.classList.add('selected');
}

function updateLoginLevels() {
  ['ben','jamal','jeffry'].forEach(h => {
    const lv = getHeroLevel(h);
    const rank = getRank(lv);
    const el = document.getElementById('loginLvl' + h.charAt(0).toUpperCase() + h.slice(1));
    if (el) el.textContent = rank.icon + ' Lv. ' + lv + ' (' + heroData[h].kills + ' Kills)';
  });
}

// ===== START =====
function goBackBP() { if (window.parent !== window) { try { parent.postMessage({ bpRealmBack: true }, location.origin); } catch (e) { location.href = '/'; } } else location.href = '/'; }
function startGame() {
  try { startGameInner(); } catch (e) {
    var box = document.getElementById('startErr');
    if (!box) { box = document.createElement('div'); box.id = 'startErr'; box.style.cssText = 'color:#ff8a8a;font-size:.7rem;margin-top:10px;word-break:break-word'; var lb = document.getElementById('loginBox'); if (lb) lb.appendChild(box); }
    box.textContent = 'Fehler beim Start: ' + (e && e.message ? e.message : e);
    try { console.error(e); } catch (x) {}
  }
}
function startGameInner() {
  const nameEl = document.getElementById('nameInput');
  const name = (window.bpUser || localStorage.getItem('robPlayerName') || nameEl.value.trim() || 'Spieler').slice(0,16);
  localStorage.setItem('robPlayerName', name);
  const heroEl = document.querySelector('.hero-card.selected');
  const heroEl2 = heroEl || document.querySelector('.hero-card');
  const hero = heroEl2 ? heroEl2.dataset.hero : 'ben';
  localStorage.setItem('robLastHero', hero);
  initMeta(hero, name);
  document.getElementById('heroPortrait').src = IMGS[hero];
  document.getElementById('heroName').textContent = name.toUpperCase() + ' | ' + heroEl2.querySelector('.hclass').textContent.toUpperCase();
  document.getElementById('loginOverlay').style.display = 'none';
  generateBoard();
  updateUI();
  log('⭐ <span style="color:var(--gold)">'+name+'</span> betritt das Reich der Bestien...');
  const lv = getHeroLevel(hero);
  if (lv > 0) log('⭐ <span style="color:var(--diamond)">Helden-Level '+lv+'! +'+(lv*2)+' ATK, '+(lv*5)+' HP Bonus!</span>');
  const ownedSkills = heroData[hero].skills;
  if (ownedSkills.length > 0) log('✨ <span style="color:var(--diamond)">'+ownedSkills.length+' Fähigkeit(en) aktiv!</span>');
}

// ===== BOSS WORLD SYSTEM =====
// Boss kommt NACH jeder 10. Runde als eigener Kampf (nicht auf dem Board)
let pendingBossNum = 0; // Welcher Boss gerade wartet (0 = keiner)

function getWorldBossNum() {
  // Welcher Boss wÄre als nÄchstes? (nach welcher Runde)
  return Math.ceil(meta.round / 10);
}
function getTotalBossesDefeated() {
  return Object.values(heroData).reduce((s,h) => s + h.bossKills, 0);
}
function getWorldBossStats(bossNum) {
  const _pm = 1 + ((typeof prestigeData !== 'undefined' && prestigeData.count) || 0) * 0.12;
  return {
    hp:  Math.floor((1000 + (bossNum - 1) * 800) * _pm),
    atk: Math.max(1, Math.floor((25   + (bossNum - 1) * 20) * _pm * (1 - ((typeof cityBonus === 'function' ? cityBonus('arena') : 0) || 0)))),
    gold: 100  * bossNum,
    diamonds: Math.max(10, 10 + (bossNum - 1) * 5)
  };
}

// ===== HELD WECHSELN =====
function showHeroReselect() {
  if (meta && getHeroLevel(meta.hero) < 100) {
    closeMenu();
    log('\u26A0\uFE0F <span style="color:#ffaa44">Held wechseln erst m\u00F6glich wenn dein aktueller Held <b>Level 100</b> erreicht! (Aktuell: Lv.' + getHeroLevel(meta.hero) + ')</span>');
    return;
  }
  // Zeige einen einfachen Hero-Select Modal
  var modal = document.getElementById('heroReselectModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'heroReselectModal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:600;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.95)';
    modal.innerHTML = '<div style="background:linear-gradient(145deg,#0a0505,#150505);border:2px solid var(--gold);border-radius:16px;padding:24px 20px;max-width:380px;width:95%">'
      + '<h2 style="font-family:Cinzel Decorative,serif;color:var(--gold);font-size:1rem;text-align:center;margin-bottom:14px">HELD AUSWÄHLEN</h2>'
      + '<div style="display:flex;gap:8px;margin-bottom:14px" id="heroReselectCards"></div>'
      + '<button class="btn btn-wide" onclick="document.getElementById(\'heroReselectModal\').style.display=\'none\'" style="width:100%">ABBRECHEN</button>'
      + '</div>';
    document.body.appendChild(modal);
  }
  var cards = document.getElementById('heroReselectCards');
  var heroes = ['ben','jamal','jeffry'];
  var hnames = {ben:'BEN',jamal:'JAMAL',jeffry:'JEFFRY'};
  cards.innerHTML = heroes.map(function(h) {
    const lv = getHeroLevel(h);
    const rank = getRank(lv);
    const isActive = meta.hero === h;
    return '<div onclick="reselectHero(\'' + h + '\')" style="flex:1;border:2px solid ' + (isActive ? 'var(--gold)' : rank.color) + ';border-radius:10px;padding:10px 6px;text-align:center;cursor:pointer;background:rgba(20,5,5,0.9)">'
      + '<div style="font-size:0.65rem;color:var(--gold);font-weight:700">' + hnames[h] + '</div>'
      + '<div style="font-size:0.6rem;color:' + rank.color + ';margin:3px 0">' + rank.icon + ' Lv.' + lv + '</div>'
      + (isActive ? '<div style="font-size:0.55rem;color:#44ff88">AKTIV</div>' : '')
      + '</div>';
  }).join('');
  modal.style.display = 'flex';
}
function reselectHero(hero) {
  if (!meta) return;
  const oldHero = meta.hero;
  meta.hero = hero;
  document.getElementById('heroPortrait').src = IMGS[hero];
  document.getElementById('heroName').textContent = meta.name.toUpperCase() + ' | ' + hero.toUpperCase();
  // Recalc stats for new hero
  initMeta(hero, meta.name);
  generateBoard();
  updateUI();
  document.getElementById('heroReselectModal').style.display = 'none';
  log('✨ <span style="color:var(--diamond)">Held gewechselt zu ' + hero.toUpperCase() + '!</span>');
}

// ===== BOARD =====
function generateBoard() {
  board = [];
  const hasEntdecker = heroData[meta.hero] && heroData[meta.hero].skills.includes('ben3');
  for (let i = 0; i < 25; i++) {
    if (i === 0) { board.push('start'); continue; } // Erstes Feld = Startzeichen
    const r = Math.random();
    const goldThresh = hasEntdecker ? 0.35 : 0.2;
    if (r < 0.35) board.push('monster|' + getMonsterType());
    else if (r < 0.35 + goldThresh) board.push('gold');
    else board.push('empty');
  }
  // Bett: nur 30% Chance dass eines erscheint, max 1 pro Board
  const bedCount = Math.random() < 0.30 ? 1 : 0;
  const emptyIndices = board.map((t, i) => t === 'empty' ? i : -1).filter(i => i > 0);
  for (let b = 0; b < bedCount && emptyIndices.length > 0; b++) {
    const ri = Math.floor(Math.random() * emptyIndices.length);
    board[emptyIndices[ri]] = 'bed';
    emptyIndices.splice(ri, 1);
  }
  drawBoard();
}

function drawBoard() {
  const g = document.getElementById('boardGrid');
  g.innerHTML = '';
  board.forEach((e, i) => {
    const d = document.createElement('div');
    d.className = 'cell';
    if (i === pos) { d.classList.add('player'); d.textContent = '\uD83E\uDD77'; }
    else if (e === 'start') { d.style.background = 'rgba(0,80,0,0.4)'; d.style.borderColor = '#44ff88'; d.textContent = '\u2691'; d.title = 'START'; }
    else if (e === 'gold') { d.classList.add('gold-cell'); d.textContent = '\uD83D\uDCB0'; }
    else if (e.startsWith('monster')) {
      d.classList.add('monster-cell');
      const mType = e.split('|')[1] || 'frog';
      d.textContent = MONSTER_EMOJIS[mType] || '\u2620\uFE0F';
      d.title = MONSTER_NAMES[mType] || 'MONSTER';
    }
    else if (e === 'bed') {
      d.style.background = 'rgba(0,60,40,0.5)';
      d.style.borderColor = '#44cc88';
      d.textContent = '\uD83D\uDECC';
      d.title = 'Bett: Heilt 50% deiner aktuellen HP';
    }
    else d.textContent = ' ';
    g.appendChild(d);
  });
}

// ===== ACTION =====
function handleAction() {
  if (inFight) { attack(); return; }
  // Wenn ein Boss wartet, muss er bekÄmpft werden
  if (pendingBossNum > 0) { startWorldBoss(pendingBossNum); return; }

  const steps = Math.floor(Math.random() * 4) + 1;
  log('👣 Du läufst <span style="color:#88aaff">' + steps + ' Meter</span> weiter.');
  pos += steps; if (window.runKick) runKick(steps);
  if (pos >= board.length) {
    meta.round++;
    prestigeData.points = (prestigeData.points || 0) + 1; savePrestige();
    pos = 0;

    // Alle 10 Runden kommt ein Boss (nach Runde 10, 20, 30, ...)
    if (meta.round % 10 === 0) {
      const bossNum = meta.round / 10;
      pendingBossNum = bossNum;
      // Auto-Run stoppen: Level N laeuft nur bis Boss N
      if (autoRunActive && autoRunData.level <= bossNum) {
        clearInterval(autoRunInterval);
        autoRunActive = false;
        updateAutoRunUI();
        log('\u26A1 <span style="color:#ffaa44">Auto-Run pausiert \u2014 Boss ' + bossNum + ' ist da! K\u00E4mpfe ihn manuell. (Upgrade nach dem Sieg verf\u00FCgbar)</span>');
      }
      const bs = getWorldBossStats(bossNum);
      log('👹 <span style="color:var(--gold)">BOSS ' + bossNum + ' erscheint! HP: ' + bs.hp + ' | ATK: ' + bs.atk + '</span>');
      updateUI();
      return;
    }

    generateBoard();
    log('👹 <span style="color:var(--gold)">Runde ' + meta.round + ' beginnt!</span>');
    updateUI();
    return;
  }
  const cell = board[pos];
  if (cell === 'start') {
    log('\u2691 <span style="color:#44ff88">Du stehst auf dem Startfeld.</span>');
    drawBoard(); updateUI(); return;
  }
  if (cell === 'bed') {
    const healAmt = Math.floor(meta.hp * 0.5);
    meta.hp = Math.min(meta.maxHp, meta.hp + healAmt);
    board[pos] = 'empty';
    log('\uD83D\uDECC <span style="color:#44ff88">Du ruhst dich im Bett aus und erholst dich! +' + healAmt + ' HP</span>');
    showDmgPopup('+' + healAmt + '\u2764', '#44ff88');
    drawBoard(); updateUI(); return;
  }
  if (cell === 'gold') {
    let g = Math.floor(Math.random() * 8) + 6;
    g = Math.floor(g * getSchurkeGoldMult());
    if (heroData[meta.hero].skills.includes('ben1') && Math.random() < 0.30) {
      g *= 2;
      showSkillPopup('🍀 GLÜCKSGRIFF! Doppeltes Gold!');
    }
    meta.gold += g;
    if (true) { questTracking.goldEarned = (questTracking.goldEarned||0) + g; saveQuestTracking(); }
    log('👹 <span style="color:var(--gold)">' + g + ' Gold gefunden!</span>');
    board[pos] = 'empty';
    showDmgPopup('+' + g + '💰', '#f0c040');
  }
  if (cell.startsWith('monster')) startFight(false, cell.split('|')[1]);
  drawBoard();
  updateUI();
}

// ===== MONSTER FACTORY =====
function getMonsterType() {
  const r = meta.round;
  const available = [];
  if (r >= 1  && r <= 10) available.push('frog');
  if (r >= 5  && r <= 15) available.push('gobold');
  if (r >= 11 && r <= 20) available.push('wolf');
  if (r >= 21 && r <= 30) available.push('bear');
  if (r >= 25 && r <= 35) available.push('golem');
  if (r >= 31 && r <= 40) available.push('snake');
  if (r >= 41 && r <= 50) available.push('spider');
  if (r >= 51 && r <= 60) available.push('freggz');
  if (r >= 61 && r <= 70) available.push('hexe');
  if (r >= 71 && r <= 80) available.push('snowman');
  if (r >= 81)             available.push('inferno');
  if (available.length === 0) available.push('frog');
  return available[Math.floor(Math.random() * available.length)];
}

function createMonster(type, isBoss) {
  const base = {
    frog:   {hp:10, atk:3,  gold:5},
    gobold: {hp:14, atk:4,  gold:8},
    wolf:   {hp:20, atk:6,  gold:10},
    bear:   {hp:30, atk:8,  gold:15},
    golem:  {hp:35, atk:7,  gold:18},
    snake:  {hp:22, atk:7,  gold:20},
    spider: {hp:26, atk:8,  gold:24},
    freggz: {hp:32, atk:9,  gold:28},
    hexe:   {hp:28, atk:10, gold:32},
    snowman:{hp:38, atk:11, gold:38},
    inferno:{hp:45, atk:14, gold:45},
    dragon1:{hp:55, atk:15, gold:25}, dragon2:{hp:80,atk:22,gold:40}, dragon3:{hp:120,atk:32,gold:65}
  }[type] || {hp:10, atk:3, gold:5};
  // Ab Runde 21: Monster werden deutlich stÄrker
  let scaleMult = meta.round >= 21 ? 2.5 : 1.5;
  const scale = (meta.round - 1) * scaleMult;
  let hp = Math.floor(base.hp + scale);
  let atk = Math.floor(base.atk + scale / 2);
  // Ab Runde 21 extra Boost
  if (meta.round >= 21) { hp = Math.floor(hp * 1.4); atk = Math.floor(atk * 1.3); }
  let gold = base.gold;
  if (isBoss) { hp *= 4; atk = Math.floor(atk * 2); gold *= 3; }
  { const _ar = (typeof cityBonus === 'function' ? cityBonus('arena') : 0) || 0; atk = Math.max(1, Math.floor(atk * (1 - _ar))); }
  { const _pm = 1 + ((typeof prestigeData !== 'undefined' && prestigeData.count) || 0) * 0.12; hp = Math.floor(hp * _pm); atk = Math.floor(atk * _pm); }
  return { type: isBoss ? 'boss_' + type : type, baseType: type, hp, maxHp: hp, atk, gold, isBoss };
}

function startWorldBoss(bossNum) {
  const bs = getWorldBossStats(bossNum);
  inFight = true;
  meta._fightTookDamage = false;
  hinterhaltAvailable = true;
  hiebAvailable = true;
  shieldActive = false;
  monstersInFight = [{
    type: 'worldboss_' + bossNum,
    baseType: 'dragon1',
    hp: bs.hp, maxHp: bs.hp,
    atk: bs.atk,
    gold: bs.gold,
    isBoss: true,
    isWorldBoss: true,
    bossNum: bossNum
  }];
  // Boss 7-9: zwei Drachen nacheinander (je 60% Leben/Kraft), der zweite kommt von rechts herein
  if (bossNum >= 7 && bossNum <= 9) {
    const m0 = monstersInFight[0];
    m0.hp = m0.maxHp = Math.floor(bs.hp * 0.6); m0.atk = Math.floor(bs.atk * 0.6);
    m0.next = { type: 'worldboss_' + bossNum + 'b', baseType: 'dragon1', hp: m0.hp, maxHp: m0.hp, atk: m0.atk, gold: bs.gold, isBoss: true, isWorldBoss: true, bossNum: bossNum };
  }
  showBossAlert('? BOSS ' + bossNum);
  renderFight();
  log('⭐ <span style="color:#ff4400">BOSS ' + bossNum + ' greift an! HP: ' + bs.hp + ' | Kraft: ' + bs.atk + '</span>');
}

// ===== FIGHT =====
function startFight(isBoss, forcedType) {
  inFight = true;
  monstersInFight = [];
  meta._fightTookDamage = false;
  // Reset per-fight ability state
  hinterhaltAvailable = true;
  hiebAvailable = true;
  shieldActive = false;
  const type = forcedType || getMonsterType();
  if (isBoss) {
    monstersInFight.push(createMonster(type, true));
    showBossAlert(MONSTER_NAMES['boss_' + type]);
  } else {
    const count = (meta.round >= 5 && Math.random() < 0.4) ? 2 : 1;
    for (let i = 0; i < count; i++) monstersInFight.push(createMonster(type, false));
  }
  renderFight();
  const names = monstersInFight.map(m => MONSTER_NAMES[m.type]).join(' & ');
  log('⚔️ <span style="color:var(--red)">' + names + ' greift an!</span>');
}

function showBossAlert(name) {
  const el = document.getElementById('bossAlert');
  document.getElementById('bossAlertTitle').textContent = '👹 ' + name + ' ERSCHEINT!';
  document.getElementById('bossAlertText').textContent = 'Besiege ihn für 💎 Diamanten!';
  el.style.display = 'block';
  setTimeout(() => el.style.display = 'none', 3000);
}

function renderFight() {
  renderAbilityBar();
  const scene = document.getElementById('battleScene');
  if (monstersInFight.length === 0) {
    scene.innerHTML = '<div id="battleBg"></div><div id="battleMessage"><h3>🏆 Sieg! Die Reise geht weiter...</h3><p>Du hörst noch das Echo des Kampfes.</p></div>';
    document.getElementById('battleBg').style.backgroundImage = 'url("'+IMGS.dungeon+'")';
    return;
  }
  let html = '<div id="battleBg"></div>';
  monstersInFight.forEach((m, i) => {
    const bossClass = m.isBoss ? ' boss-monster' : '';
    const monsterLabel = m.isWorldBoss ? ('👹 WORLD BOSS ' + m.bossNum) : (m.isBoss ? '⚔️ BOSS' : '');
    const displayName = m.isWorldBoss ? ('Boss ' + m.bossNum) : (MONSTER_NAMES[m.type] || m.type);
    html += `<div class="monster-slot${bossClass}" id="mslot${i}">
      ${monsterLabel ? '<div class="boss-label">' + monsterLabel + '</div>' : ''}
      <img src="${getMonsterImg(m.baseType)}" alt="${m.type}" id="mimg${i}">
      <div class="monster-name">${displayName}</div>
      <div class="monster-hp">❤️ ${m.hp}/${m.maxHp}</div>
      <div class="monster-atk" style="font-size:0.6rem;color:#ff8844;margin-top:2px">⚔️ KRAFT: ${m.atk}</div>
    </div>`;
  });
  scene.innerHTML = html;
  document.getElementById('battleBg').style.cssText = `position:absolute;inset:0;background-image:url("${IMGS.dungeon}");background-size:cover;background-position:center;opacity:0.25;border-radius:10px;`;
}

function attack() {
  if (window.runSwing) runSwing();
  if (!monstersInFight.length) return;
  const target = monstersInFight[0];
  const skills = heroData[meta.hero].skills;
  let dmg = meta.attack + Math.floor(Math.random() * 3);
  // Kritischer Treffer: 10% Chance (Jaeger: 100% extra, sonst 50% extra)
  const critChance = hasClass('jaeger') ? 0.15 : 0.10;
  const critMult = hasClass('jaeger') ? 2.0 : 1.5;
  let isCrit = Math.random() < critChance;
  if (isCrit) { dmg = Math.floor(dmg * critMult); if (true) { questTracking.critHits = (questTracking.critHits||0) + 1; saveQuestTracking(); } showSkillPopup('\u26A1 KRIT!'); }

  // Wutanfall: HP < 50% ? +50% Angriff
  if (skills.includes('jamal1') && meta.hp < meta.maxHp * 0.5) {
    dmg = Math.floor(dmg * 1.5);
  }

  // Todesschlag: 10% Chance sofort töten
  let instantKill = false;
  if (skills.includes('jamal3') && !target.isBoss && Math.random() < 0.10) {
    instantKill = true;
    showSkillPopup('💀 TODESSCHLAG!');
  }

  if (instantKill) {
    target.hp = 0;
  } else {
    target.hp -= dmg;
  }

  const imgEl = document.getElementById('mimg0');
  if (imgEl) { imgEl.classList.add('hit-flash'); setTimeout(() => imgEl.classList.remove('hit-flash'), 300); }
  if (true) { questTracking.damageDone = (questTracking.damageDone||0) + (instantKill ? target.hp : dmg); saveQuestTracking(); }
  if (!instantKill) showDmgPopup('-' + dmg + ' ⚔️', '#ff4400');
  const _tname = target.isWorldBoss ? ('Boss ' + target.bossNum) : (MONSTER_NAMES[target.type] || target.type);
  log('⚔️ Du triffst <span style="color:var(--red)">' + _tname + '</span> für <span style="color:#ff6644">' + (instantKill ? 'INSTANT KILL' : dmg + ' Schaden') + '</span>.');

  if (target.hp <= 0) {
    const wasBoss = target.isBoss;
    const _dname = target.isWorldBoss ? ('Boss ' + target.bossNum) : (MONSTER_NAMES[target.type] || target.type);
    if (!target.isWorldBoss) {
      let killGold = target.gold;
      // Beutemacher (jamal4): +2 Gold pro Kill
      if (skills.includes('jamal4')) { killGold += 2; }
      // Schurke: +30% Gold
      killGold = Math.floor(killGold * getSchurkeGoldMult());
      if (typeof cityBonus === 'function') killGold = Math.floor(killGold * cityBonus('gold'));
      if (window.__kamGoldM) killGold = Math.floor(killGold * window.__kamGoldM());
      // (Energie-Regen läuft am Ende von attack())
      // Reset hinterhaltAvailable after fight ends (set here too)
      log('\uD83D\uDC79 <span style="color:var(--gold)">' + _dname + ' besiegt! +' + killGold + ' Gold</span>');
      meta.gold += killGold; if (true) { questTracking.goldEarned = (questTracking.goldEarned||0) + killGold; saveQuestTracking(); }
    }
    if (!target.isBoss && !meta._fightTookDamage) { questTracking.monstersNoDmg = (questTracking.monstersNoDmg||0) + 1; saveQuestTracking(); }
    // Monster Lexikon Kill-Tracking
    if (!target.isWorldBoss) {
      var _lexType = target.baseType || target.type;
      if (_lexType) {
        monsterKills[_lexType] = (monsterKills[_lexType] || 0) + 1;
        saveMonsterKills();
        checkMonsterMilestone(_lexType);
      }
    }
    // level-up check based on monster kills (only once per kill)
    const prevLv = getHeroLevel(meta.hero);
    meta.kills++;
    try { tryDropItem(!!target.isBoss); } catch(e) {}
    heroData[meta.hero].kills = (heroData[meta.hero].kills||0) + 1;
    const newLv = getHeroLevel(meta.hero);
    if (newLv > prevLv) showLevelUp(newLv);

    if (wasBoss && !target.next) {
      meta.bossKillsThisRun++;
      const totalBossKillsBefore = Object.values(heroData).reduce((s,h)=>s+h.bossKills,0);
      heroData[meta.hero].bossKills++;
      if (true) { questTracking.bossesKilled = (questTracking.bossesKilled||0) + 1; saveQuestTracking(); }

      // World Boss Belohnungen
      if (target.isWorldBoss) {
        const bs = getWorldBossStats(target.bossNum);
        // First kill bonus: 100 diamonds, then 5 per kill
        const isFirstBossKill = bossFirstKills.indexOf(target.bossNum) === -1;
        const diamondReward = window.__kamDiaReward ? window.__kamDiaReward(isFirstBossKill ? 100 : 15) : (isFirstBossKill ? 100 : 15);
        if (isFirstBossKill) { bossFirstKills.push(target.bossNum); saveBossFirstKills(); }
        let goldReward = bs.gold;
        // Champion-Beute (jeffry4): Boss-Gold +50%
        const _allCls = (typeof playerClasses !== 'undefined' ? playerClasses : (playerClass ? [playerClass] : []));
        if (skills.includes('jeffry4') || _allCls.some(function(c){return c.id==='schurke';})) {
          if (skills.includes('jeffry4')) { goldReward = Math.floor(goldReward * 1.5); showSkillPopup('\uD83E\uDD47 CHAMPION-BEUTE! +50% Gold!'); }
        }
        meta.diamonds += diamondReward; globalDiamonds += diamondReward; saveDiamonds(globalDiamonds);
        meta.gold += goldReward;
        if (true) { questTracking.goldEarned = (questTracking.goldEarned||0) + goldReward; saveQuestTracking(); }
        showDmgPopup('+' + diamondReward + ' DIAS', '#44ddff');
        log('<span style="color:#44ddff">\uD83D\uDC8E BOSS ' + target.bossNum + ' besiegt!' + (isFirstBossKill ? ' ERSTMAL!' : '') + ' +' + diamondReward + ' Diamanten, +' + goldReward + ' Gold!</span>');
        // Auto-Run Stufe freischaltbar nach Boss-Kill
        if (autoRunData.level < target.bossNum) {
          const nextCost = 1000 * Math.pow(2, target.bossNum - 1);
          log('<span style="color:#ffaa44">\u26A1 AUTO-RUN Stufe ' + target.bossNum + ' freigeschalten! Kaufe es im Shop f\u00FCr ' + nextCost + ' Gold. (L\u00E4uft bis Boss ' + target.bossNum + ')</span>');
        }
        pendingBossNum = 0; meta._wasWorldBoss = true; // Boss erledigt, nÄchste Runde starten
        // Prestige-Token
        prestigeData.top = Math.max(prestigeData.top || 0, target.bossNum); savePrestige();
        // Nur Bosse ab Boss 5 zählen (kein Boss-1-Farmen): alle 10 solcher Siege gibt es ein Token
        if (target.bossNum >= 5) {
          const hb = (prestigeData.hb || 0) + 1;
          prestigeData.hb = hb;
          if (hb % 10 === 0) {
            prestigeData.prestigeAvailable = (prestigeData.prestigeAvailable || 0) + 1;
            log('<span style="color:#cc44ff">💜 PRESTIGE VERFÜGBAR! (' + prestigeData.prestigeAvailable + ' Token)</span>');
          }
          savePrestige();
        }
      } else {
        // Normaler Boss (alter Code-Pfad, falls noch irgendwo genutzt)
        const diamondReward = totalBossKillsBefore === 0 ? 100 : 10;
        meta.diamonds += diamondReward; globalDiamonds += diamondReward; saveDiamonds(globalDiamonds);
        showDmgPopup('+' + diamondReward + ' DIAS', '#44ddff');
        log('<span style="color:#44ddff">BOSS besiegt! +' + diamondReward + ' Diamanten!</span>');
        const totalBossKillsNow = totalBossKillsBefore + 1;
        if (totalBossKillsNow >= 50 && !prestigeData.unlocked) {
          prestigeData.unlocked = true; savePrestige();
          log('<span style="color:#cc44ff">💜 PRESTIGE FREIGESCHALTET!</span>');
        }
        if (totalBossKillsBefore === 0) setTimeout(() => showClassModal(), 1500);
      }
    } // end if (wasBoss)

    if (target.isWorldBoss && target.next) {
      // Erster Drache stirbt (Animation), danach kommt der zweite von rechts herein
      const nx = target.next; target.next = null;
      window.__turnLock = true;
      const el0 = document.getElementById('mimg0'); if (el0) el0.classList.add('kdie');
      saveHeroData(); updateUI();
      setTimeout(function() {
        monstersInFight[0] = nx;
        renderFight(); updateUI();
        const e2 = document.getElementById('mimg0'); if (e2) e2.classList.add('kenter');
        log('<span style="color:#ff6644">Der zweite Drache greift an!</span>');
        setTimeout(function() { window.__turnLock = false; }, 700);
      }, 800);
      return;
    }
    saveHeroData();
    monstersInFight.shift();
  }

  if (monstersInFight.length === 0) {
    inFight = false;
    // World Boss: neue Runde starten
    if (pendingBossNum === 0 && meta._wasWorldBoss) {
      meta._wasWorldBoss = false;
      generateBoard();
      log('👹 <span style="color:var(--gold)">Runde ' + meta.round + ' wird fortgesetzt!</span>');
    } else {
      board[pos] = 'empty';
    }
    renderFight();
    updateUI();
    return;
  }

  // Zugwechsel: erst schlaegt der Held, dann (verzoegert) der Gegner
  renderFight(); updateUI();
  window.__turnLock = true;
  setTimeout(function(){ window.__turnLock = false; _counterTurn(); }, 900);
  function _counterTurn() {
  // Counter attack
  let totalDmg = 0;
  let blocked = false;
  monstersInFight.forEach(m => {
    let md = m.atk + Math.floor(Math.random() * 3);
    if (window.__kamMonHit) { md = window.__kamMonHit(m, md); if (md <= 0) return; }
    if (window.__kamShield) md = Math.max(1, Math.round(md * (1 - window.__kamShield / 100)));
    // Jaeger: 5% Ausweichen
    // Jaeger: 10% Dodge (improved from 5%)
    const _dodgeChance = hasClass('jaeger') ? 0.10 : (playerClass && playerClass.id === 'jaeger' ? 0.10 : 0);
    if (_dodgeChance > 0 && Math.random() < _dodgeChance) {
      if (true) { questTracking.attacksDodged = (questTracking.attacksDodged||0) + 1; saveQuestTracking(); }
      showSkillPopup('Ausgewichen!'); return;
    }
    // Paladin Schild: blockt naechsten Angriff
    if (shieldActive) {
      shieldActive = false;
      showSkillPopup('\uD83D\uDEE1\uFE0F Schild! Geblockt!');
      log('<span style="color:#ccaa44">\uD83D\uDEE1\uFE0F SCHILD hat den Angriff geblockt!</span>');
      return;
    }
    // Eisenhaut: -2 Schaden
    if (skills.includes('jeffry1')) md = Math.max(1, md - 2);
    // Schildwall: 15% Chance blocken
    if (skills.includes('jeffry2') && Math.random() < 0.15) {
      blocked = true;
      showSkillPopup('🛡️ SCHILDWALL! Blockiert!');
      log('✨ <span style="color:var(--diamond)">SCHILDWALL! Angriff geblockt!</span>');
      return;
    }
    // Rache: +1 ATK stapeln
    if (skills.includes('jeffry3')) {
      meta.attack++;
      meta.revengeStacks = (meta.revengeStacks || 0) + 1;
    }
    // Blutdurst: 20% Schaden zurÜck
    if (skills.includes('jamal2')) {
      const leech = Math.floor(md * 0.2);
      if (leech > 0) { meta.hp = Math.min(meta.hp + leech, meta.maxHp); }
    }
    // === GEGNER SPEZIALFAEHIGKEITEN ===
    // Ab Runde 5: Wolf-Wutanfall (25% Doppelschaden)
    if (meta.round >= 5 && m.baseType === 'wolf' && Math.random() < 0.25) {
      md *= 2;
      log('<span style="color:#ff4400">WUTANFALL! ' + MONSTER_NAMES[m.type] + ' trifft doppelt!</span>');
    }
    // Ab Runde 8: Gegner heilt sich (20% wenn HP < 40%)
    if (meta.round >= 8 && m.hp < m.maxHp * 0.4 && Math.random() < 0.20) {
      const heal = Math.floor(m.maxHp * 0.10);
      m.hp = Math.min(m.maxHp, m.hp + heal);
      log('<span style="color:#44cc44">' + MONSTER_NAMES[m.type] + ' heilt sich um ' + heal + ' HP!</span>');
    }
    // Ab Runde 12: Vergiftungs-Angriff (15% Chance, 3 Runden je 3 Schaden)
    if (meta.round >= 12 && Math.random() < 0.15) {
      meta.poisoned = (meta.poisoned || 0) + 3;
      log('<span style="color:#88cc00">VERGIFTET! 3 Schaden fuer 3 Angriffe!</span>');
    }
    // Boss-Drache: Feueratem-Bonus +5 Schaden immer
    if (m.isBoss) {
      md += 5;
      if (Math.random() < 0.3) {
        md += Math.floor(m.atk * 0.5);
        log('<span style="color:#ff6600">FEUERATEM! Extra Feuerschaden!</span>');
      }
    }
    // Gift-Tick
    if (meta.poisoned && meta.poisoned > 0) {
      meta.hp -= 3;
      meta.poisoned--;
      log('<span style="color:#88cc00">Gift: -3 HP (' + meta.poisoned + ' verbleibend)</span>');
    }
    totalDmg += md;
    meta.hp -= md;
    meta._fightTookDamage = true;
    const _mname = m.isWorldBoss ? ('Boss ' + m.bossNum) : (MONSTER_NAMES[m.type] || m.type);
    log('⚠️ <span style="color:#cc4444">' + _mname + ' trifft dich für ' + md + '!</span>');
  });
  if (totalDmg > 0) showDmgPopup('-' + totalDmg + '❤', '#cc2200');

  if (meta.hp <= 0) {
    meta.hp = 0;
    try { if (window.__kamDeathSoul) window.__kamDeathSoul(); } catch(e) {}
    saveHeroData();
    updateUI();
    setTimeout(showDeath, 400);
    return;
  }

  // Decrement ability cooldowns after each attack round
  Object.keys(abilityCooldowns).forEach(function(id) {
    if (abilityCooldowns[id] > 0) abilityCooldowns[id]--;
  });

  renderFight();
  updateUI();
  } // end _counterTurn
}

// ===== RANG & LEVEL SYSTEM =====
const RANKS = [
  { minLv:0,  name:'Anfaenger', color:'#aaaaaa', icon:'' },
  { minLv:10, name:'Bronze',    color:'#cd7f32', icon:'🥉' },
  { minLv:25, name:'Silber',    color:'#cccccc', icon:'🥈' },
  { minLv:50, name:'Gold',      color:'#ffd700', icon:'🥇' },
  { minLv:80, name:'Legendaer', color:'#ff8800', icon:'👑' },
  { minLv:90, name:'Mythic',    color:'#cc44ff', icon:'?' },
  { minLv:100,name:'Mystisch',  color:'#ff44cc', icon:'?' },
];
function getRank(lv) {
  var r = RANKS[0];
  for (var i = 0; i < RANKS.length; i++) { if (lv >= RANKS[i].minLv) r = RANKS[i]; }
  return r;
}
