const RANK_LEVELS = {10:'Bronze',25:'Silber',50:'Gold',80:'Legendaer',90:'Mythic',100:'Mystisch'};

function showLevelUp(newLevel) {
  if (newLevel > (questTracking.maxHeroLv||0)) { questTracking.maxHeroLv = newLevel; saveQuestTracking(); }
  const el = document.getElementById('levelUpAlert');
  const reward = window.__kamLvReward ? window.__kamLvReward(newLevel) : (LEVEL_REWARDS[newLevel - 1] || {g:0,h:0,a:0,d:0});
  const rankUp = RANK_LEVELS[newLevel];
  const rank = getRank(newLevel);
  let parts = [];
  if (reward.h > 0) { meta.maxHp += reward.h; meta.hp = Math.min(meta.hp + reward.h, meta.maxHp); parts.push('+' + reward.h + ' HP'); }
  if (reward.a > 0) { meta.attack += reward.a; parts.push('+' + reward.a + ' ATK'); }
  if (reward.g > 0) { meta.gold += reward.g; parts.push('+' + reward.g + ' Gold'); }
  if (reward.d > 0) { meta.diamonds += reward.d; globalDiamonds += reward.d; saveDiamonds(globalDiamonds); parts.push('+' + reward.d + ' Dias'); }
  let msg = 'Level ' + newLevel;
  if (rankUp) msg += ' | ' + rank.icon + ' ' + rankUp.toUpperCase() + ' RANG!';
  if (parts.length) msg += ': ' + parts.join(', ');
  document.getElementById('levelUpText').textContent = msg;
  el.style.display = 'block';
  setTimeout(() => el.style.display = 'none', 3500);
  const color = rank.color;
  log('<span style="color:' + color + '">LEVEL UP! ' + msg + '</span>');
  heroData[meta.hero].kills = heroData[meta.hero].kills; // trigger save
  saveHeroData();
  updateUI();
}

// ===== DEATH =====
function showDeath() {
  pendingBossNum = 0;
  // Prestige 10+: Offline-Modus | automatisch nach 5 Sekunden respawnen wenn Auto-Run aktiv war
  if (prestigeData.count >= 10 && autoRunActive) {
    autoRunActive = false; clearInterval(autoRunInterval);
    log('<span style="color:#cc88ff">? OFFLINE-MODUS: Respawn in 5 Sekunden...</span>');
    setTimeout(() => {
      respawn();
      // Restart auto-run (autoRunActive is already false, toggleAutoRun flips to true)
      if (autoRunData.level > 0) { autoRunActive = false; toggleAutoRun(); }
    }, 5000);
  }
  document.getElementById('overlayText').textContent =
    meta.name + ' ist in Runde ' + meta.round + ' gefallen. ' + meta.kills + ' Feinde besiegt.';
  document.getElementById('overlayGold').textContent = '💰 ' + meta.gold + ' Gold verfügbar';
  document.getElementById('overlayDiamond').textContent = '\uD83D\uDC8E ' + meta.diamonds + ' Diamanten';
  const totalBossKillsSD = Object.values(heroData).reduce((s,h)=>s+h.bossKills,0);
  const dsEl = document.getElementById('deathSkillShopSection');
  if (dsEl) dsEl.style.display = totalBossKillsSD > 0 ? '' : 'none';
  renderSkillShop();
  updateShopPricesUI();
  updateAutoRunUI();
  document.getElementById('overlayMsg').style.display = 'flex';
}

function respawn() {
  document.getElementById('overlayMsg').style.display = 'none';
  // Full reset - back to round 1, keep hero name/class
  const hero = meta.hero;
  const name = meta.name;
  initMeta(hero, name);
  pos = 0;
  inFight = false;
  monstersInFight = [];
  pendingBossNum = 0;
  meta._wasWorldBoss = false;
  meta._fightTookDamage = false;
  generateBoard();
  updateUI();
  log('🌟 <span style="color:#88aaff">Ein neues Abenteuer beginnt... Runde 1</span>');
  const lv = getHeroLevel(hero);
  if (lv > 0) log('⭐ <span style="color:var(--diamond)">Helden-Level ' + lv + ' aktiv!</span>');
}

// ===== SCHWARZMARKT (Tod-Shop) =====
function loadShopBonuses() {
  try { const d = localStorage.getItem('robShopBonuses'); return d ? JSON.parse(d) : {hp:0,atk:0,gold:0}; } catch(e) { return {hp:0,atk:0,gold:0}; }
}
function saveShopBonuses() {
  try { localStorage.setItem('robShopBonuses', JSON.stringify(shopBonuses)); } catch(e) {}
}
function buyItem(type) {
  const cost = type==='hp' ? shopPrices.hp : shopPrices.atk;
  if (meta.gold < cost) { log('⚠️ <span style="color:#cc4444">Nicht genug Gold!</span>'); return; }
  meta.gold -= cost;
  questTracking.goldSpent = (questTracking.goldSpent||0) + cost;
  questTracking.shopBuys = (questTracking.shopBuys||0) + 1;
  saveQuestTracking();
  if (type==='hp') {
    shopBonuses.hp += 10;
    meta.maxHp += 10;
    meta.hp = Math.min(meta.hp + 10, meta.maxHp);
    saveShopBonuses();
    log('\uD83D\uDCB0 <span style="color:#44ff88">Max-HP +10! (n\u00E4chstes Mal: \uD83D\uDCB0'+(shopPrices.hp+25)+')</span>');
    shopPrices.hp += 25;
  }
  if (type==='atk') {
    shopBonuses.atk += 3;
    meta.attack += 3;
    saveShopBonuses();
    log('\u2B50 <span style="color:#ffaa44">Angriff +3! (n\u00E4chstes Mal: \uD83D\uDCB0'+(shopPrices.atk+25)+')</span>');
    shopPrices.atk += 25;
  }
  saveShopPrices();
  document.getElementById('overlayGold').textContent = '💰 ' + meta.gold + ' Gold verfügbar';
  updateShopPricesUI();
  updateUI();
}

function buyAutoRun() {
  const nextLevel = autoRunData.level + 1;
  // Check if boss for this level has been killed
  const totalBossKills = heroData[meta.hero].bossKills;
  if (totalBossKills < nextLevel) {
    log('⚠️ <span style="color:#cc4444">Besiege erst Boss ' + nextLevel + ' um Auto-Run Stufe ' + nextLevel + ' freizuschalten!</span>');
    return;
  }
  const cost = 1000 * Math.pow(2, nextLevel - 1);
  if (meta.gold < cost) { log('\u26A0\uFE0F <span style="color:#cc4444">Nicht genug Gold! Brauche ' + cost + ' Gold.</span>'); return; }
  meta.gold -= cost;
  questTracking.goldSpent = (questTracking.goldSpent||0) + cost;
  questTracking.shopBuys  = (questTracking.shopBuys||0)  + 1;
  saveQuestTracking();
  autoRunData.level = nextLevel;
  saveAutoRun();
  log('\u26A1 <span style="color:#ffaa44">Auto-Run Stufe ' + nextLevel + ' gekauft! L\u00E4uft bis Boss ' + nextLevel + '.</span>');
  document.getElementById('overlayGold').textContent = '💰 ' + meta.gold + ' Gold verfügbar';
  updateAutoRunUI();
  updateUI();
}

function updateShopPricesUI() {
  const hp = document.getElementById('shopCostHp');
  const atk = document.getElementById('shopCostAtk');
  if (hp) hp.textContent = '💰 ' + shopPrices.hp;
  if (atk) atk.textContent = '💰 ' + shopPrices.atk;
}

function updateAutoRunUI() {
  const nameEl = document.getElementById('autoRunShopName');
  const costEl = document.getElementById('autoRunShopCost');
  const descEl = document.getElementById('autoRunShopDesc');
  const btnEl = document.getElementById('autoRunBtn');
  if (!nameEl) return;
  const nextLevel = autoRunData.level + 1;
  const totalBossKills = heroData[meta.hero] ? heroData[meta.hero].bossKills : 0;
  const unlocked = totalBossKills >= nextLevel;
  const cost = 1000 * Math.pow(2, nextLevel - 1);
  nameEl.textContent = 'AUTO-RUN Lv.' + nextLevel;
  if (!unlocked) {
    costEl.textContent = '\uD83D\uDC80 Boss ' + nextLevel + ' n\u00F6tig';
    descEl.textContent = 'Besiege Boss ' + nextLevel + ' um Stufe ' + nextLevel + ' freizuschalten';
  } else {
    costEl.textContent = '\uD83D\uDCB0 ' + cost + ' Gold';
    descEl.textContent = 'L\u00E4uft automatisch bis Boss ' + nextLevel + ' (Runde ' + (nextLevel * 10) + ')';
  }
  // Update in-game auto-run button
  if (btnEl) {
    if (autoRunData.level === 0) {
      btnEl.textContent = '\u26A1 AUTO-RUN: NICHT GEKAUFT';
      btnEl.disabled = true;
      btnEl.className = 'btn btn-wide btn-disabled';
    } else {
      const rangeLabel = 'bis Boss ' + autoRunData.level;
      btnEl.textContent = autoRunActive
        ? '\u26A1 AUTO-RUN STOPPEN (Lv.' + autoRunData.level + ' \u2014 ' + rangeLabel + ')'
        : '\u26A1 AUTO-RUN STARTEN (Lv.' + autoRunData.level + ' \u2014 ' + rangeLabel + ')';
      btnEl.disabled = false;
      btnEl.className = 'btn btn-wide btn-diamond';
    }
  }
}

function toggleAutoRun() {
  if (autoRunData.level === 0) return;
  autoRunActive = !autoRunActive;
  if (autoRunActive) {
    const delay = autoRunData.level <= 1 ? 1200 : autoRunData.level <= 3 ? 800 : autoRunData.level <= 6 ? 600 : 400;
    autoRunInterval = setInterval(() => {
      if (!autoRunActive || document.getElementById('overlayMsg').style.display === 'flex') {
        clearInterval(autoRunInterval); autoRunActive = false; updateAutoRunUI(); return;
      }
      handleAction();
    }, delay);
    log('⭐ <span style="color:var(--diamond)">Auto-Run Stufe ' + autoRunData.level + ' gestartet!</span>');
  } else {
    clearInterval(autoRunInterval);
    log('⭐ <span style="color:#aaa">Auto-Run gestoppt.</span>');
  }
  updateAutoRunUI();
}

// ===== SKILL SHOP =====
function renderSkillShop() {
  const hero = meta.hero;
  const hd = heroData[hero];
  const bossKills = hd.bossKills;
  const ownedSkills = hd.skills;
  const diamonds = meta.diamonds;

  document.getElementById('skillProgress').textContent =
    '💀 Boss-Kills: ' + bossKills + '/10 zum Freischalten | ?? ' + diamonds + ' Diamanten';

  const container = document.getElementById('deathSkillItems');
  container.innerHTML = '';
  const skillList = SKILLS[hero] || [];
  skillList.forEach(sk => {
    const div = document.createElement('div');
    const owned = ownedSkills.includes(sk.id);
    const unlocked = bossKills >= 10;
    div.className = 'skill-item' + (owned ? ' owned' : !unlocked ? ' locked' : '');
    div.innerHTML = `
      <div class="sk-icon">${sk.icon}</div>
      <div class="sk-name">${sk.name}</div>
      <div class="sk-desc">${sk.desc}</div>
      ${owned ? '<div class="sk-owned">\u2713 AKTIV</div>' :
        !unlocked ? '<div class="sk-lock">\uD83D\uDD12 10 Boss-Kills n\u00F6tig</div>' :
        '<div class="sk-cost">\uD83D\uDC8E ' + sk.cost + '</div>'}
    `;
    if (!owned && unlocked) {
      div.onclick = () => buySkill(sk.id, sk.cost, hero);
    }
    container.appendChild(div);
  });
}

function buySkill(skillId, cost, hero) {
  if (meta.diamonds < cost) {
    log('⚠️ <span style="color:#cc4444">Nicht genug Diamanten!</span>');
    return;
  }
  if (heroData[hero].skills.includes(skillId)) return;
  meta.diamonds -= cost;
  globalDiamonds -= cost;
  saveDiamonds(globalDiamonds);
  questTracking.diasSpent = (questTracking.diasSpent||0) + cost;
  questTracking.skillsBought = (questTracking.skillsBought||0) + 1;
  saveQuestTracking();
  heroData[hero].skills.push(skillId);
  saveHeroData();
  document.getElementById('overlayDiamond').textContent = '\uD83D\uDC8E ' + meta.diamonds + ' Diamanten';
  renderSkillShop();
  // Find skill name
  const sk = (SKILLS[hero] || []).find(s => s.id === skillId);
  log('✨ <span style="color:var(--diamond)">' + (sk ? sk.name : skillId) + ' freigeschaltet!</span>');
  updateUI();
}

// ===== UI UPDATE =====
function updateUI() {
  if (meta) savePersistentGold(meta.gold);
  document.getElementById('statHp').textContent = meta.hp + '/' + meta.maxHp;
  document.getElementById('statAtk').textContent = meta.attack;
  document.getElementById('statGold').textContent = meta.gold;
  document.getElementById('statDiamond').textContent = meta.diamonds;
  // display progress toward next level (reset each level)
  const killsProg = getKillsThisLevel(meta.hero);
  const killsReq = getKillsForNext(meta.hero);
  document.getElementById('statKills').textContent = killsReq ? killsProg + '/' + killsReq : killsProg;

  document.getElementById('heroLevelNum').textContent = getHeroLevel(meta.hero);
  // if showing progress, update kill tooltip
  const killEl = document.getElementById('statKills');
  if (killEl) killEl.title = 'Total Kills: ' + (heroData[meta.hero].kills||0);

  const _clsLvEl = document.getElementById('classLevelNum');
  if (_clsLvEl) _clsLvEl.textContent = getClassLevel();
  const _prestEl = document.getElementById('prestigeNum');
  if (_prestEl) _prestEl.textContent = prestigeData.count || 0;

  // Inventar-Bonus ist direkt in meta.attack / meta.maxHp eingerechnet — kein separater Bonus-Bar
  var bonusBar = document.getElementById('invBonusBar');
  if (bonusBar) bonusBar.style.display = 'none';

  const pct = Math.max(0, meta.hp / meta.maxHp * 100);
  document.getElementById('hpBar').style.width = pct + '%';
  document.getElementById('hpBar').style.background = pct > 50
    ? 'linear-gradient(90deg,#22aa44,#44ff88)'
    : pct > 25 ? 'linear-gradient(90deg,#aa6600,#ff9900)'
    : 'linear-gradient(90deg,#660000,#cc0000)';

  document.getElementById('actionBtn').textContent = inFight
    ? '⚔️ ANGREIFEN'
    : pendingBossNum > 0
      ? '⚠️ BOSS ' + pendingBossNum + ' KÄMPFEN!'
      : '⚔️ VORWÄRTS';

  // Active skills display
  const ownedSkills = heroData[meta.hero] ? heroData[meta.hero].skills : [];
  const allSkills = SKILLS[meta.hero] || [];
  const activeDiv = document.getElementById('activeSkills');
  if (ownedSkills.length > 0) {
    activeDiv.innerHTML = ownedSkills.map(sid => {
      const sk = allSkills.find(s => s.id === sid);
      return sk ? `<span class="skill-badge">${sk.icon} ${sk.name}</span>` : '';
    }).join('');
  } else {
    activeDiv.innerHTML = '';
  }

  // Rang-Rahmen: Hero Portrait basierend auf aktuellem Rang
  const heroLv = getHeroLevel(meta.hero);
  const currentRank = getRank(heroLv);
  const portrait = document.getElementById('heroPortrait');
  if (portrait) {
    portrait.style.border = '3px solid ' + currentRank.color;
    portrait.style.boxShadow = '0 0 10px ' + currentRank.color + '55';
    portrait.style.borderRadius = '8px';
  }
  const rankBadgeEl = document.getElementById('rankDisplayBadge');
  if (rankBadgeEl) rankBadgeEl.textContent = currentRank.icon + ' ' + currentRank.name;

  // Boss-Warnung wenn Boss wartet
  const _roundBadge = document.getElementById('roundBadge');
  if (_roundBadge) {
    if (pendingBossNum > 0) {
      _roundBadge.style.borderColor = '#ff4400';
      _roundBadge.style.color = '#ff4400';
      _roundBadge.textContent = '';
      _roundBadge.innerHTML = '⚔️ BOSS ' + pendingBossNum;
    } else {
      _roundBadge.style.borderColor = 'var(--gold2)';
      _roundBadge.style.color = 'var(--gold)';
      _roundBadge.innerHTML = 'RUNDE <span id="roundNum">' + meta.round + '</span>';
    }
  }

  // Klassen-Button immer sichtbar — Hinweis wenn Level < 10
  const classBtn = document.getElementById('menuClassBtn');
  if (classBtn) {
    classBtn.style.display = 'block';
    const _heroLvForClass = getHeroLevel(meta.hero);
    const _maxSlots = getMaxClassSlots(_heroLvForClass);
    const _hasOpenSlot = playerClasses.length < _maxSlots && _heroLvForClass >= 10;
    if (_heroLvForClass < 10) {
      classBtn.style.opacity = '0.5';
      classBtn.title = 'Erreiche Level 10 um eine Klasse zu waehlen!';
      classBtn.textContent = 'KLASSE WAEHLEN';
    } else if (_hasOpenSlot && playerClasses.length > 0) {
      classBtn.style.opacity = '1';
      classBtn.title = '';
      classBtn.textContent = '\u2694\uFE0F ' + playerClasses.map(function(c){return c.name;}).join('+') + ' + NEUE KLASSE';
    } else if (playerClasses.length > 0) {
      classBtn.style.opacity = '1';
      classBtn.title = '';
      classBtn.textContent = '\u2694\uFE0F ' + playerClasses.map(function(c){return c.name;}).join('+') + ' (wechseln)';
    } else {
      classBtn.style.opacity = '1';
      classBtn.title = '';
      classBtn.textContent = 'KLASSE WAEHLEN';
    }
  }

  drawBoard();
}

// ===== LOG =====
function log(msg) {
  const l = document.getElementById('logBox');
  l.innerHTML += msg + '<br>';
  l.scrollTop = l.scrollHeight;
}

// ===== POPUPS =====
function showDmgPopup(text, color) {
  const d = document.createElement('div');
  d.className = 'dmg-popup';
  d.textContent = text;
  d.style.cssText = `color:${color};top:45%;left:${40+Math.random()*20}%;text-shadow:0 0 10px ${color};`;
  document.body.appendChild(d);
  setTimeout(() => d.remove(), 800);
}
function showSkillPopup(text) {
  const d = document.createElement('div');
  d.className = 'skill-popup';
  d.textContent = text;
  document.body.appendChild(d);
  setTimeout(() => d.remove(), 1200);
}

