// ===== KLASSEN-SYSTEM =====
function loadPlayerClasses() {
  try {
    const d = localStorage.getItem('robPlayerClass');
    if (!d) return [];
    const parsed = JSON.parse(d);
    // Migration: old format was single object, new is array
    if (Array.isArray(parsed)) return parsed;
    if (parsed && parsed.id) return [parsed]; // old single class -> array
    return [];
  } catch(e) { return []; }
}
function savePlayerClasses(arr) {
  try { localStorage.setItem('robPlayerClass', JSON.stringify(arr)); } catch(e) {}
}
// Legacy compat: playerClass = first class or null
let playerClasses = loadPlayerClasses();
let playerClass = playerClasses.length > 0 ? playerClasses[0] : null;

// How many class slots a hero level allows
function getMaxClassSlots(heroLv) {
  if (heroLv < 10) return 0;
  if (heroLv < 30) return 1;
  if (heroLv < 50) return 2;
  return 3;
}

