    closeMenu();
    log('\u26A0\uFE0F <span style="color:#ffaa44">Du musst erst <b>Helden-Level 10</b> erreichen um eine Klasse zu w\u00E4hlen! (Aktuell: Lv.' + getHeroLevel(meta.hero) + ')</span>');
