async function submitScore() {
  saveRunScore();
  if (!meta || meta.round < 2) { log('⚠️ <span style="color:#cc4444">Spiel erst etwas weiter!</span>'); return; }
  if (!onlineAccount) { log('⚠️ <span style="color:#cc4444">Bitte erst einloggen!</span>'); showAccountModal(); return; }
  const score = calcScore(meta.round, meta.kills, meta.bossKillsThisRun||0, prestigeData.count);
  const _pcs2 = (typeof playerClasses !== 'undefined' ? playerClasses : (playerClass ? [playerClass] : []));
  const entry = {
    name: (meta && meta.name) || localStorage.getItem('robPlayerName') || (onlineAccount.displayName) || 'Unbekannt',
    email: onlineAccount.email || '', uid: onlineAccount.uid,
    hero: meta.hero, avatar: selectedAvatar || 'knight',
    heroLevel: getHeroLevel(meta.hero),
    classIds: _pcs2.map(function(c){ return c.id; }),
    classNames: _pcs2.map(function(c){ return c.name; }),
    score, round: meta.round, kills: meta.kills,
    bossKills: meta.bossKillsThisRun || 0, prestige: prestigeData.count,
    date: new Date().toLocaleDateString('de-DE')
  };
  try {
    const existing = await db.ref('leaderboard/' + onlineAccount.uid).once('value');
    const prev = existing.val();
    if (!prev || score > prev.score) {
      await db.ref('leaderboard/' + onlineAccount.uid).set(entry);
      log('⭐ <span style="color:#44ff88">Score gespeichert! ' + score + ' Punkte ??</span>');
    } else {
      log('⚡ <span style="color:#ffaa44">Highscore bereits hÖher (' + prev.score + ' Punkte).</span>');
    }
  } catch(e) { log('⚡ <span style="color:#ffaa44">Offline gespeichert.</span>'); }
}

