var realmNewsLast = 0;
function realmNewsLoad(markSeen) {
  var box = document.getElementById('realmNewsBox');
  var api = window.parent && window.parent.tfApi;
  if (!api) { if (box) box.textContent = 'Keine News.'; return; }
  api('/api/realm/news', {}).then(function (r) {
    if (!r || !r.ok) { if (box) box.textContent = 'Keine News.'; return; }
    realmNewsLast = r.lastId || 0;
    var seen = 0; try { seen = parseInt(localStorage.getItem('rob_news_seen') || '0', 10) || 0; } catch (e) {}
    var dot = document.getElementById('realmNewsDot');
    if (dot) dot.style.display = (realmNewsLast > seen && !markSeen) ? 'inline' : 'none';
    if (markSeen) { try { localStorage.setItem('rob_news_seen', String(realmNewsLast)); } catch (e) {} }
    if (!box) return;
    var esc = function (t) { return String(t == null ? '' : t).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };
    box.innerHTML = r.news.length ? r.news.map(function (n, i) {
      var d = new Date(n.ts), ds = ('0' + d.getDate()).slice(-2) + '.' + ('0' + (d.getMonth() + 1)).slice(-2) + '.' + d.getFullYear();
      var c = (n.en && /^en/i.test(navigator.language || '')) ? n.en : n.de;
      return '<div style="border:1.5px solid ' + (i === 0 ? 'var(--gold)' : '#553') + ';border-radius:12px;padding:12px;background:rgba(0,0,0,.35);margin-bottom:10px"><div style="font-size:0.6rem;color:#aa8844;font-weight:700">' + ds + '</div><div style="font-weight:700;color:var(--gold);margin:3px 0">' + esc(c.title) + '</div><div style="white-space:pre-wrap">' + esc(c.text) + '</div></div>';
    }).join('') : 'Noch keine News.';
  }).catch(function () { if (box) box.textContent = 'Keine News.'; });
}
function showSpieleModal() {
  document.getElementById('spieleModal').style.display = 'flex';
  realmNewsLoad(true);
}
function closeSpieleModal() {
  document.getElementById('spieleModal').style.display = 'none';
}
