// ===== AUTO-LOGIN & CLOUD RESTORE =====
var _gameStarted = false;

function _startGameFromSave() {
  if (_gameStarted) return;
  var savedName = localStorage.getItem('robPlayerName');
  var savedHero = localStorage.getItem('robLastHero') || 'ben';
  if (!savedName || !localStorage.getItem('robLastHero')) return; // kein gespeicherter Spieler → Login-Screen zeigen

  _gameStarted = true;

  // In-Memory Variablen aus (evtl. frisch geladenem) localStorage holen
  heroData = loadHeroData();
  globalDiamonds = loadDiamonds();
  playerClasses = loadPlayerClasses();
  playerClass = playerClasses.length > 0 ? playerClasses[0] : null;

  // Meta neu initialisieren (wendet Klassen-/Item-Boni an)
  initMeta(savedHero, savedName);

  // Gold und Diamanten aus gespeichertem Stand wiederherstellen
  var savedGold = parseInt(localStorage.getItem('robGold') || '0') || 0;
  meta.gold = savedGold;
  meta.diamonds = globalDiamonds;

  // UI vorbereiten
  document.getElementById('heroPortrait').src = IMGS[savedHero];
  var heroEl = document.querySelector('.hero-card[data-hero="' + savedHero + '"]');
  var hclass = heroEl ? heroEl.querySelector('.hclass') : null;
  document.getElementById('heroName').textContent = savedName.toUpperCase() + (hclass ? ' | ' + hclass.textContent.toUpperCase() : '');

  // Name-Input + Hero-Karte vorauswaehlen (fuer den Fall dass Overlay auftaucht)
  var nameEl = document.getElementById('nameInput');
  if (nameEl) nameEl.value = savedName;
  document.querySelectorAll('.hero-card').forEach(function(c) {
    c.classList.toggle('selected', c.dataset.hero === savedHero);
  });

  document.getElementById('loginOverlay').style.display = 'none';
  generateBoard();
  updateUI();
  log('\u2764 <span style="color:var(--gold)">Willkommen zur\u00FCck, ' + savedName + '!</span>');
}

