window._robAuthFallbackTimer = setTimeout(function() {
  _startGameFromSave();
}, 3000);

// ===== MUSIC PLAYLIST =====
const PLAYLIST = ['music/1.mp3','music/2.mp3','music/3.mp3','music/4.mp3','music/5.mp3','music/6.mp3'];
let _playlistOrder = [];
let _playlistIdx = 0;
const _bgPlayer = new Audio();
_bgPlayer.volume = 0.1;

function _shufflePlaylist() {
  _playlistOrder = PLAYLIST.slice().sort(() => Math.random() - 0.5);
  _playlistIdx = 0;
}
function _playNextTrack() {
  if (_playlistIdx >= _playlistOrder.length) _shufflePlaylist();
  _bgPlayer.src = _playlistOrder[_playlistIdx++];
  _bgPlayer.play().then(function() { _musicPlaying = true; _updateMusicBtn(); }).catch(function() { _musicPlaying = false; _updateMusicBtn(); });
}
_bgPlayer.addEventListener('ended', function() { _playNextTrack(); });
var _musicPlaying = false;

function _updateMusicBtn() {
  var btn = document.getElementById('musicPlayBtn');
  if (btn) btn.textContent = _musicPlaying ? '\u23F8\uFE0F' : '\u25B6\uFE0F';
}

function toggleMusicPlay() {
  if (_musicPlaying) {
    _bgPlayer.pause();
    _musicPlaying = false;
    _updateMusicBtn();
  } else {
    if (_playlistOrder.length === 0) _shufflePlaylist();
    if (!_bgPlayer.src || _bgPlayer.src === window.location.href) {
      _playNextTrack();
    } else {
      _bgPlayer.play().then(function() {
        _musicPlaying = true;
        _updateMusicBtn();
      });
    }
  }
}

// Autoplay nach erster Nutzerinteraktion
var _autoplayDone = false;
function _tryAutoplay() {
  if (_autoplayDone) return;
  _autoplayDone = true;
  if (_playlistOrder.length === 0) _shufflePlaylist();
  _playNextTrack();
}
// Musik direkt beim Start versuchen (Browser erlauben das oft nicht), sonst bei der ersten Beruehrung
(function() {
  _autoplayDone = false;
  function go() { if (_autoplayDone) return; _tryAutoplay(); }
  if (_playlistOrder.length === 0) _shufflePlaylist();
  _bgPlayer.src = _playlistOrder[_playlistIdx++];
  _bgPlayer.play().then(function() { _autoplayDone = true; _musicPlaying = true; _updateMusicBtn(); }).catch(function() {
    ['pointerdown', 'touchstart', 'click', 'keydown'].forEach(function(ev) {
      var h = function() { _bgPlayer.play().then(function() { _autoplayDone = true; _musicPlaying = true; _updateMusicBtn(); }).catch(function(){}); ['pointerdown','touchstart','click','keydown'].forEach(function(e2){ document.removeEventListener(e2, h, true); }); };
      document.addEventListener(ev, h, true);
    });
  });
})();

