// ===== BROWSER/HANDY ZURUECK-TASTE =====
// Verhindert dass die Zurueck-Taste das Fenster schliesst
// Stattdessen: immer das Menue oeffnen
(function() {
  var MODAL_IDS = [
    'classModal','questModal','levelTableModal','top100Modal','classLevelModal',
    'prestigeLevelModal','inventoryModal','diaShopModal','accountModal','prestigeModal','spieleModal'
  ];

  function showMenu() {
    var p = document.getElementById('menuPanel');
    if (p) p.style.display = 'block';
    var ml = document.getElementById('menuLoginBtn');
    if (ml) ml.textContent = onlineAccount ? 'LOGOUT' : 'LOGIN';
  }

  function hideAllModals() {
    MODAL_IDS.forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
  }

  // Zwei Eintraege pushen damit immer ein "Puffer"-Eintrag da ist
  history.replaceState({ rob: true }, '');
  history.pushState({ rob: true }, '');

  window.addEventListener('popstate', function() {
    hideAllModals();
    showMenu();
    // Sofort neuen Eintrag pushen damit naechster Druck wieder abgefangen wird
    setTimeout(function() {
      history.pushState({ rob: true }, '');
    }, 0);
  });
})();

